functions.HandCompare:
int HandCompare(Card *hand1, Card *hand2)
{
    HandType hand1_type = HandClassify(hand1);
    HandType hand2_type = HandClassify(hand2);
    int diff = hand1_type - hand2_type;
    if (diff != 0)
        return diff;
    for (size_t i = 0; i < 5; ++i)
    {
        int cmp = CardCompare(&hand1[i], &hand2[i]);
        if (cmp != 0)
            return cmp;
    }
    return 0;
}

functions.HandSort:
void HandSort(Card *hand)
{
    Bucket buckets[13] = {{{{InvalidRank, InvalidSuit}}, 0}};
    for (size_t i = 0; i < 5; ++i)
    {
        size_t bucket_index = hand[i].rank - 1;
        BucketAdd(&buckets[bucket_index], &hand[i]);
    }
    size_t index = 0;
    for (size_t count = 4; count > 0; --count)
    {
        for (size_t j = 13 - 1; j != (size_t)-1; --j)
        {
            if (buckets[j].count == count)
            {
                memcpy(&hand[index], &buckets[j].cards, sizeof(Card) * count);
                index += count;
            }
        }
    }
}

functions.HandClassify:
HandType HandClassify(Card *cards)
{
    if (HandIsFlush(cards))
    {
        if (HandIsStraight(cards))
            return StraightFlush;
        if (HandIsWheel(cards))
            return WheelFlush;
        return Flush;
    }
    else
    {
        if (HandIsFourOfAKind(cards))
            return FourOfAKind;
        if (HandIsFullHouse(cards))
            return FullHouse;
        if (HandIsStraight(cards))
            return Straight;
        if (HandIsWheel(cards))
            return Wheel;
        if (HandIsThreeOfAKind(cards))
            return ThreeOfAKind;
        if (HandIsTwoPair(cards))
            return TwoPair;
        if (HandIsPair(cards))
            return Pair;
        return HighCard;
    }
}

functions.HandIsValid:
_Bool HandIsValid(const Card *cards)
{
    for (size_t i = 0; i < 5; ++i)
        if (!CardIsValid(&cards[i]))
            return 0;
    return 1;
}

functions.HandIsStraightFlush:
static _Bool HandIsStraightFlush(const Card *cards)
{
    return HandIsStraight(cards) && HandIsFlush(cards);
}

functions.HandIsWheelFlush:
static _Bool HandIsWheelFlush(const Card *cards)
{
    return HandIsWheel(cards) && HandIsFlush(cards);
}

functions.HandIsFourOfAKind:
static _Bool HandIsFourOfAKind(const Card *cards)
{
    return cards[0].rank == cards[3].rank;
}

functions.HandIsFullHouse:
static _Bool HandIsFullHouse(const Card *cards)
{
    return cards[0].rank == cards[2].rank && cards[3].rank == cards[4].rank;
}

functions.HandIsFlush:
static _Bool HandIsFlush(const Card *cards)
{
    for (size_t i = 1; i < 5; ++i)
        if (cards[i].suit != cards[0].suit)
            return 0;
    return 1;
}

functions.HandIsStraight:
static _Bool HandIsStraight(const Card *cards)
{
    return cards[0].rank == cards[1].rank + 1 && cards[0].rank == cards[4].rank + 4;
}

functions.HandIsWheel:
static _Bool HandIsWheel(const Card *cards)
{
    return cards[0].rank == Ace && cards[1].rank == Five;
}

functions.HandIsThreeOfAKind:
static _Bool HandIsThreeOfAKind(const Card *cards)
{
    return cards[0].rank == cards[2].rank;
}

functions.HandIsTwoPair:
static _Bool HandIsTwoPair(const Card *cards)
{
    return cards[2].rank == cards[3].rank;
}

functions.HandIsPair:
static _Bool HandIsPair(const Card *cards)
{
    return cards[0].rank == cards[1].rank;
}

