functions.indexOf:
size_t indexOf(char c, const char *chars, size_t N)
{
    for (size_t i = 0; i < N; ++i)
    {
        if (chars[i] == c)
        {
            return i + 1;
        }
    }
    return 0;
}

functions.NewCard:
Card NewCard(Rank rank, Suit suit)
{
    Card card = {.rank = rank, .suit = suit};
    if (CardIsValid(&card))
        return card;
    else
        return INVALID_CARD;
}

functions.NewCardFromChars:
Card NewCardFromChars(char r, char s)
{
    Rank rank = CharToRank(r);
    Suit suit = CharToSuit(s);
    return NewCard(rank, suit);
}

functions.NewCardFromString:
Card NewCardFromString(char *s)
{
    if (strlen(s) != 2)
        return INVALID_CARD;
    else
        return NewCardFromChars(s[0], s[1]);
}

functions.CardCompare:
int CardCompare(const Card *a, const Card *b)
{
    return a->rank - b->rank;
}

functions.CardEqual:
_Bool CardEqual(const Card *a, const Card *b)
{
    return a->rank == b->rank && a->suit == b->suit;
}

functions.CardToString:
void CardToString(char *out, const Card *c)
{
    if (!CardIsValid(c))
    {
        out[0] = '-';
        out[1] = '-';
    }
    else
    {
        out[0] = "23456789TJQKA"[(int)c->rank - 1];
        out[1] = "cdhs"[(int)c->suit - 1];
    }
    out[2] = '\0';
}

functions.CardIsValid:
_Bool CardIsValid(const Card *c)
{
    return (c->rank >= Deuce && c->rank <= Ace && c->suit >= Club && c->suit <= Spade);
}

functions.CardSwap:
void CardSwap(Card *a, Card *b)
{
    Card t = *a;
    *a = *b;
    *b = t;
}

